            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "O maior pecado, depois do pecado, é a publicação do pecado.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Se só me faltassem os outros, vá; um homem consola-se mais ou menos das pessoas que perde. Mas falto eu mesmo, e esta lacuna é tudo.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Deus é o poeta. A música é de Satanás, jovem maestro de muito futuro, que aprendeu no conservatório do céu.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Que é demasiada metafísica para um só tenor, não há dúvida; mas a perda da voz explica tudo, e há filósofos que são, em resumo, tenores desempregados.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Há coisas que só se aprendem tarde; é mister nascer com elas para fazê-las cedo. E melhor é naturalmente cedo que artificialmente tarde.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "As pessoas valem o que vale a afeição da gente, e é daí que mestre Povo tirou aquele adágio que quem o feio ama bonito lhe parece.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "O melhor drama está no espectador e não no palco.", Author = "Machado de Assis" },
