            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Era homem como os outros; outros Aquiles andam por aí que são da cabeça aos pés um imenso calcanhar.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "O ridículo é uma espécie de lastro da alma quando ela entra no mar da vida; algumas fazem toda a navegação sem outra espécie de carregamento.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "A ausência diminui as paixões medíocres e aumenta as grandes, como o vento apaga as velas e atiça as fogueiras.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Não há decepções possíveis para um viajante, que apenas vê de passagem o lado belo da natureza humana e não ganha tempo de conhecer-lhe o lado feio.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Importuna coisa é a felicidade alheia quando somos vítima de algum infortúnio.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Porque não há raciocínio nem documento que nos explique melhor a intenção de um ato do que o próprio autor do ato.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "A vida é uma enorme loteria; os prêmios são poucos, os malogrados inúmeros, e com os suspiros de uma geração é que se amassam as esperanças de outra.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Porque o adjetivo é a alma do idioma, a sua porção idealista e metafísica. O substantivo é a realidade nua e crua, é o naturalismo do vocabulário.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Sentenças latinas, ditos históricos, versos célebres, brocardos jurídicos, máximas, é de bom aviso trazê-los contigo para os discursos de sobremesa, de felicitação ou de agradecimento.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Quem não for cavaleiro, que o pareça.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Meu amigo, a imaginação e o espírito têm limites; a não ser a famosa botelha dos saltimbancos e a credulidade dos homens, nada conheço inesgotável debaixo do sol.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "A ciência, disse ele a Sua Majestade, é o meu emprego único; Itaguaí é o meu universo.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "A índole natural da ciência é a longanimidade;", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Mas a ciência tem o inefável dom de curar todas as mágoas;", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "A saúde da alma, bradou ele, é a ocupação mais digna do médico.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Preso por ter cão, preso por não ter cão.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Verdade é que, se todos os gostos fossem iguais, o que seria do amarelo?", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "A vida é um livro, no dizer de todos os poetas. Negro para uns, dourado para outros. Nao o tenho negro; mas os parenteses que se me abriu no meio das melhores paginas, esse foi angustioso e sombrio.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "O coração é o relógio da vida. Quem não o consulta, anda naturalmente fora do tempo.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "O comentário da lei é a eterna malícia.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Francamente, eu não gosto de gente que venha adivinhando e compondo um livro que está sendo escrito com método...", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Meu bom xadrez, meu querido xadrez, tu que és o jogo dos silenciosos", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Não se demonstra uma cocada, come-se. Comê-la é defini-la.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Alguma coisa escapa ao naufrágio das ilusões.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Eu não sou homem que recuse elogios. Amo-os; eles fazem bem à alma e até ao corpo. As melhores digestões da minha vida são as dos jantares em que sou brindado.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Está morto: podemos elogiá-lo à vontade.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "A melhor definição do amor não vale um beijo.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Esquecer é uma necessidade. A vida é uma lousa, em que o destino, para escrever um novo caso, precisa apagar o caso escrito.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Há em todas as coisas um sentido filosófico.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Palavra puxa palavra, uma idéia traz outra, e assim se faz um livro, um governo, ou uma revolução, alguns dizem mesmo que assim é que a natureza compôs as suas espécies.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "A arte de viver consiste em tirar o maior bem do maior mal.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Basta amar para escolher bem; o diabo que fosse era sempre boa escolha.", Author = "Machado de Assis" },
