            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "A vida é cheia de obrigações que a gente cumpre por mais vontade que tenha de as infringir deslavadamente.", Author = "Machado de Assis" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Machado_de_Assis", Text = "Há sempre uma qualidade nos contos, que os torna superiores aos grandes romances, se uns e outros são medíocres: é serem curtos.", Author = "Machado de Assis" },
